#include <stdio.h>
#include <ctype.h>

void capitalize(char *s) {
    for (int i = 0; s[i] != '\0'; i++) {
        if (i == 0 || s[i - 1] == ' ') {
            s[i] = toupper(s[i]);
        }
    }
}

int main() {
    char s[] = "red green blue";
    capitalize(s);
    printf("%s\n", s);
    return 0;
}
